module Top;
  typedef int queue_t[$];
  typedef int array_t[];
  function automatic queue_t tail(queue_t q);
    return q[1:$];
  endfunction
  initial begin
    queue_t a, b, q; array_t d; bit c = 1;
    a = '{1, 2}; b = '{3}; d = '{5, 6};
    q = c ? a : b;
    $display("[%0d %0d]", q.size(), q[0]);
    q = tail('{1, 2, 3});
    $display("[%0d %0d]", q.size(), q[0]);
    q = d;
    $display("[%0d %0d]", q.size(), q[0]);
  end
endmodule
